INSERT INTO `seo_settings` (`id`, `page_type`, `page_identifier`, `meta_title`, `meta_description`, `meta_keywords`, `og_title`, `og_description`, `og_image`, `twitter_title`, `twitter_description`, `twitter_image`, `canonical_url`, `robots`, `schema_markup`, `custom_head`, `priority`, `change_frequency`, `is_active`, `createdAt`, `updatedAt`) VALUES
(1, 'global', NULL, 'Peruana de Informática | Equipos Tecnológicos en Perú', 'Venta de laptops, computadoras, monitores, periféricos y equipos informáticos de calidad en todo Perú. Las mejores marcas y precios.', 'laptop, computadora, monitor, periféricos, tecnología, informática, Perú, equipos', 'Peruana de Informática - Tecnología de Calidad', 'Tu tienda de confianza para equipos informáticos en Perú', NULL, NULL, NULL, NULL, '/', 'index,follow', NULL, NULL, 1.0, 'weekly', 1, '2025-10-28 22:33:59', '2025-10-28 22:33:59'),
(2, 'home', NULL, 'Inicio | Peruana de Informática', 'Descubre las mejores ofertas en laptops, computadoras y equipos informáticos. Envíos a todo Perú. ¡Compra ahora!', 'inicio, ofertas, laptops, computadoras, envíos Perú', 'Peruana de Informática - Inicio', 'Las mejores ofertas en tecnología', NULL, NULL, NULL, NULL, '/', 'index,follow', NULL, NULL, 1.0, 'daily', 1, '2025-10-28 22:33:59', '2025-10-28 22:33:59'),
(3, 'products', NULL, 'Productos | Peruana de Informática', 'Explora nuestro catálogo completo de productos tecnológicos: laptops, monitores, periféricos y más. Calidad garantizada.', 'productos, catálogo, laptops, monitores, periféricos, tecnología', 'Catálogo de Productos - Peruana de Informática', 'Descubre todos nuestros productos tecnológicos', NULL, NULL, NULL, NULL, '/products', 'index,follow', NULL, NULL, 0.9, 'daily', 1, '2025-10-28 22:33:59', '2025-10-28 22:33:59'),
(4, 'categories', NULL, 'Categorías | Peruana de Informática', 'Navega por nuestras categorías de productos tecnológicos organizadas para encontrar exactamente lo que necesitas.', 'categorías, productos, organizado, tecnología', 'Categorías de Productos', 'Productos organizados por categorías', NULL, NULL, NULL, NULL, '/categories', 'index,follow', NULL, NULL, 0.8, 'weekly', 1, '2025-10-28 22:33:59', '2025-10-28 22:33:59'),
(5, 'contact', NULL, 'Contacto | Peruana de Informática', 'Contáctanos para consultas, soporte técnico o información sobre nuestros productos. Estamos aquí para ayudarte.', 'contacto, soporte, consultas, información, ayuda', 'Contáctanos - Peruana de Informática', 'Estamos aquí para ayudarte', NULL, NULL, NULL, NULL, '/contacto', 'index,follow', NULL, NULL, 0.7, 'monthly', 1, '2025-10-28 22:33:59', '2025-10-28 22:33:59'),
(6, 'blog', NULL, 'Blog | Peruana de Informática', 'Mantente al día con las últimas noticias, reviews y guías sobre tecnología en nuestro blog especializado.', 'blog, noticias, reviews, guías, tecnología', 'Blog de Tecnología', 'Noticias y guías tecnológicas', NULL, NULL, NULL, NULL, '/blog', 'index,follow', NULL, NULL, 0.6, 'weekly', 1, '2025-10-28 22:33:59', '2025-10-28 22:33:59');
