  `id` int(11) NOT NULL,
  `page_type` varchar(50) NOT NULL,
  `page_identifier` varchar(255) DEFAULT NULL COMMENT 'Identificador específico (slug, id, etc.)',
  `meta_title` varchar(255) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
