  `custom_head` text DEFAULT NULL COMMENT 'HTML personalizado para el head',
  `priority` decimal(2,1) NOT NULL DEFAULT 0.5,
  `change_frequency` enum('always','hourly','daily','weekly','monthly','yearly','never') NOT NULL DEFAULT 'weekly',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Configuraciones SEO para diferentes páginas del sitio';

